/// <reference types="node" />
// Deterministic parsers, tested on SYNTHETIC statements in the real bunq and
// Revolut layouts (test-fixtures/parsers, generated by scripts/make-fixtures.mjs).
import { readFile } from "node:fs/promises";
import { describe, expect, it } from "vitest";
import { bunq } from "./bunq";
import { parseWithBankParser } from "./index";
import { cleanMerchant } from "./merchant";
import { extractLines, parseAmount, parseDate } from "./pdf-text";

const fixture = (name: string) => readFile(new URL(`../../../test-fixtures/${name}`, import.meta.url).pathname);
const expected = async (name: string) => JSON.parse(await readFile(new URL(`../../../test-fixtures/parsers/${name}`, import.meta.url).pathname, "utf8"));

describe("bunq parser", () => {
	it("parses every transaction of a multi-page bunq statement, exactly and deterministically", async () => {
		const pdf = new Uint8Array(await fixture("parsers/bunq-real-layout.pdf"));
		const want = await expected("bunq-real-layout.json");
		const a = await parseWithBankParser(pdf);
		const b = await parseWithBankParser(pdf);
		expect(a).toEqual(b);
		if (a.status !== "parsed") throw new Error(JSON.stringify(a));
		expect(a.parser).toBe("bunq");
		const s = a.statement;
		expect(s).toMatchObject({ bank: "bunq", account: "NL54BUNQ2025123456", period_start: "2026-09-01", period_end: "2026-10-31", opening_balance: want.opening, closing_balance: want.closing });
		expect(s.transactions.map((t) => [t.date, t.amount])).toEqual(want.transactions.map((t: { date: string; amount: number }) => [t.date, t.amount]));
		expect(s.transactions.filter((t) => t.date === "2026-10-14" && t.amount === -4.6)).toHaveLength(2);
		expect(s.transactions.every((t) => t.merchant)).toBe(true);
	});

	it("fails validation (so the AI path is used) when the balances don't add up", async () => {
		const lines = await extractLines(new Uint8Array(await fixture("parsers/bunq-real-layout.pdf")));
		const closingLine = lines.find((l) => l.text.startsWith("Saldo op 2026-10-31"))!;
		closingLine.items.at(-1)!.text = "€ 1,00";
		const r = bunq.parse(lines);
		expect(r).toEqual({ ok: false, reason: "balances don't reconcile" });
	});
});

describe("Revolut parser", () => {
	it("parses each currency section separately and skips pending transactions", async () => {
		const pdf = new Uint8Array(await fixture("parsers/revolut-real-layout.pdf"));
		const want = await expected("revolut-real-layout.json");
		const a = await parseWithBankParser(pdf);
		if (a.status !== "parsed") throw new Error(JSON.stringify(a));
		expect(a.parser).toBe("revolut");
		const s = a.statement;
		expect(s).toMatchObject({ bank: "Revolut", account: "NL09REVO0123456789", currency: "EUR", opening_balance: want.opening });
		expect(s.transactions.map((t) => [t.date, t.amount, t.currency])).toEqual(
			want.transactions.map((t: { date: string; amount: number; currency: string }) => [t.date, t.amount, t.currency]),
		);
		expect(s.transactions.some((t) => t.description.includes("Pending"))).toBe(false);
		expect(new Set(s.transactions.map((t) => t.currency))).toEqual(new Set(["EUR", "USD"]));
		// Card numbers are left out of descriptions; merchants are the row titles.
		expect(s.transactions.some((t) => t.description.includes("Card:"))).toBe(false);
		expect(s.transactions.map((t) => t.merchant)).toEqual(want.transactions.map((t: { merchant: string }) => cleanMerchant(t.merchant)));
	});
});

describe("detection", () => {
	it("leaves other layouts to the AI extraction", async () => {
		for (const f of ["ing-like-2026-09.pdf", "revolut-like-2026-09.pdf", "bunq-like-2026-10.pdf"]) {
			expect((await parseWithBankParser(new Uint8Array(await fixture(f)))).status).toBe("unsupported");
		}
	});
});

describe("helpers", () => {
	it("parses amounts in Dutch and English formats", () => {
		expect(parseAmount("+ € 1.234,56")).toBe(1234.56);
		expect(parseAmount("- € 9,99")).toBe(-9.99);
		expect(parseAmount("€1,234.56")).toBe(1234.56);
		expect(parseAmount("-€12.50")).toBe(-12.5);
		expect(parseAmount("$85.50")).toBe(85.5);
		expect(parseAmount("Bedrag")).toBeNull();
	});
	it("parses dates", () => {
		expect(parseDate("2026-10-01")).toBe("2026-10-01");
		expect(parseDate("Sep 9, 2026")).toBe("2026-09-09");
		expect(parseDate("1 Oct 2026")).toBe("2026-10-01");
		expect(parseDate("01-10-2026")).toBe("2026-10-01");
		expect(parseDate("Card: 1234")).toBeNull();
	});
	it("cleans merchant names", () => {
		expect(cleanMerchant("Albert Heijn 1234")).toBe("Albert Heijn");
		expect(cleanMerchant("Lidl 123 Enschede")).toBe("Lidl");
		expect(cleanMerchant("CCV*Foto Studio")).toBe("Foto Studio");
		expect(cleanMerchant("Arjen via Tikkie")).toBe("Arjen");
		expect(cleanMerchant("Revolut**1234*")).toBe("Revolut");
		expect(cleanMerchant("*0096*")).toBeNull();
		expect(cleanMerchant("Google Play Revolut Rate €1.00 = $1.12")).toBe("Google Play");
		expect(cleanMerchant("BOLT.EUR2608200637")).toBe("BOLT");
	});
});
